PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','publisher','editor','admin')),verified INTEGER NOT NULL DEFAULT 0,adult INTEGER NOT NULL CHECK(adult=1),active INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,subject TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS articles(id INTEGER PRIMARY KEY,game_id INTEGER REFERENCES games(id),owner_id INTEGER REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('review','news')),status TEXT NOT NULL CHECK(status IN ('draft','published','archived')),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS views(article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,visitor TEXT NOT NULL,day INTEGER NOT NULL,created INTEGER NOT NULL,UNIQUE(article_id,visitor,day));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,target TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ratings(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE,score REAL NOT NULL CHECK(score>=0 AND score<=10 AND score*2=CAST(score*2 AS INTEGER)),updated INTEGER NOT NULL,PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','deleted')),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS publisher_requests(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS business(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',notes TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY,owner_id INTEGER REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('recruitment','giveaway')),status TEXT NOT NULL CHECK(status IN ('draft','pending','rejected','published','archived')),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE,data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',consent INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,UNIQUE(user_id,activity_id));
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE,data TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(user_id,activity_id));
CREATE TABLE IF NOT EXISTS draws(activity_id INTEGER PRIMARY KEY REFERENCES activities(id),snapshot TEXT NOT NULL,winners TEXT NOT NULL,commitment TEXT NOT NULL,seed TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS awards(id INTEGER PRIMARY KEY,activity_id INTEGER REFERENCES activities(id),user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'pending',note TEXT NOT NULL DEFAULT '',updated INTEGER NOT NULL,UNIQUE(activity_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS draw_secrets(activity_id INTEGER PRIMARY KEY REFERENCES activities(id),seed TEXT NOT NULL,commitment TEXT NOT NULL);
